// AUDIO. Phoneme, word and phrase clips are GENERATED by scripts/audio/gen_audio.py (espeak-ng RP voice, plus a
// small formant synthesiser for /m n l r b d g/) and listed in public/audio/manifest.json. They are stand-ins for
// the trained-voice recordings the spec requires, and every file still needs a human phonics specialist's ear.
// If a clip is missing (or audio fails to load) we fall back to a tone for sounds and browser speech for words,
// so the prototype never goes silent. Dynamic text (e.g. the child's nickname) can only use browser speech.
let ctx: AudioContext | null = null;
let muted = false;
const ac = (): AudioContext | null => {
  try {
    ctx ??= new AudioContext();
    return ctx;
  } catch {
    return null;
  }
};

interface Manifest {
  phonemes: Record<string, string[]>;
  words: Record<string, string>;
  phrases: Record<string, string>;
  sources?: Record<string, string>;
}
let manifest: Manifest | null = null;
const buffers = new Map<string, AudioBuffer>();
const inflight = new Map<string, Promise<AudioBuffer | null>>();
let currentVoice: AudioBufferSourceNode | null = null;

const url = (rel: string) => `${import.meta.env.BASE_URL}audio/${rel}`;

const loadBuffer = (rel: string): Promise<AudioBuffer | null> => {
  const hit = buffers.get(rel);
  if (hit) return Promise.resolve(hit);
  let p = inflight.get(rel);
  if (!p) {
    p = (async () => {
      try {
        const a = ac();
        if (!a) return null;
        const res = await fetch(url(rel));
        if (!res.ok) return null;
        const buf = await a.decodeAudioData(await res.arrayBuffer());
        buffers.set(rel, buf);
        return buf;
      } catch {
        return null;
      }
    })();
    inflight.set(rel, p);
  }
  return p;
};

/**
 * Fetch an accent's manifest and decode every phoneme clip up front so touch-to-sound stays fast.
 * Calling it again with another accent swaps the whole pack (buffers are keyed by file path, so nothing clashes).
 */
export const initAudio = async (accent: string): Promise<void> => {
  try {
    const res = await fetch(url(`${accent}/manifest.json`));
    if (!res.ok) {
      manifest = null; // tone/speech fallback
      return;
    }
    const m = (await res.json()) as Manifest;
    await Promise.all(Object.values(m.phonemes).flat().map(loadBuffer));
    manifest = m;
  } catch {
    manifest = null;
  }
};
export const audioSource = (phoneme: string): string => manifest?.sources?.[phoneme] ?? 'tone (no clip)';
export const hasWord = (w: string): boolean => !!manifest?.words[w.toLowerCase()];

export const unlockAudio = (): void => {
  void ac()?.resume();
};
export const setMuted = (m: boolean): void => {
  muted = m;
  if (m) {
    window.speechSynthesis?.cancel();
    currentVoice?.stop();
  }
};

const play = (buf: AudioBuffer, gain = 1, exclusive = false): Promise<void> =>
  new Promise((resolve) => {
    const a = ac();
    if (!a || muted) return resolve();
    if (exclusive) {
      try { currentVoice?.stop(); } catch { /* already stopped */ }
    }
    const src = a.createBufferSource();
    const g = a.createGain();
    g.gain.value = gain;
    src.buffer = buf;
    src.connect(g).connect(a.destination);
    src.onended = () => resolve();
    if (exclusive) currentVoice = src;
    src.start();
  });

const SCALE = [261.6, 293.7, 329.6, 392.0, 440.0, 523.3, 587.3, 659.3, 784.0, 880.0, 1046.5, 1174.7];
const freqFor = (key: string): number => {
  let hash = 0;
  for (const ch of key) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return SCALE[hash % SCALE.length] as number;
};

const tone = (freq: number, dur: number, type: OscillatorType = 'sine', gain = 0.18, delay = 0): void => {
  const a = ac();
  if (!a || muted) return;
  const t0 = a.currentTime + delay;
  const o = a.createOscillator();
  const g = a.createGain();
  o.type = type;
  o.frequency.value = freq;
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(gain, t0 + 0.02);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  o.connect(g).connect(a.destination);
  o.start(t0);
  o.stop(t0 + dur + 0.05);
};

/** Play an isolated sound (a phoneme key such as "s", "k", "a"). */
export const blip = (phoneme: string): void => {
  const files = manifest?.phonemes[phoneme];
  const buf = files ? buffers.get(files[Math.floor(Math.random() * files.length)] as string) : undefined;
  if (buf) void play(buf, 1.0);
  else tone(freqFor(phoneme), 0.32, 'triangle', 0.22);
};
export const tap = (): void => tone(660, 0.07, 'sine', 0.1);

// ---- game sound effects (synthesised; these are UI sounds, not phonics content) ----
const sweep = (f0: number, f1: number, dur: number, type: OscillatorType = 'sine', gain = 0.16, delay = 0): void => {
  const a = ac();
  if (!a || muted) return;
  const t0 = a.currentTime + delay;
  const o = a.createOscillator();
  const g = a.createGain();
  o.type = type;
  o.frequency.setValueAtTime(f0, t0);
  o.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
  g.gain.setValueAtTime(gain, t0);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  o.connect(g).connect(a.destination);
  o.start(t0);
  o.stop(t0 + dur + 0.05);
};
const noise = (dur: number, gain = 0.12, lowpass = 1800, delay = 0): void => {
  const a = ac();
  if (!a || muted) return;
  const n = Math.floor(a.sampleRate * dur);
  const buf = a.createBuffer(1, n, a.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = a.createBufferSource();
  const f = a.createBiquadFilter();
  const g = a.createGain();
  f.type = 'lowpass';
  f.frequency.value = lowpass;
  g.gain.value = gain;
  src.buffer = buf;
  src.connect(f).connect(g).connect(a.destination);
  src.start(a.currentTime + delay);
};
export const sfx = {
  pop: () => sweep(500, 900, 0.09, 'sine', 0.14),
  whoosh: () => noise(0.35, 0.09, 1400),
  thud: () => { sweep(140, 60, 0.14, 'sine', 0.22); noise(0.06, 0.08, 500); },
  chomp: () => { sweep(260, 110, 0.1, 'square', 0.07); sweep(300, 120, 0.1, 'square', 0.07, 0.11); },
  boing: () => sweep(220, 520, 0.22, 'sine', 0.16),
  sparkle: () => [1319, 1568, 2093].forEach((f, i) => tone(f, 0.16, 'sine', 0.07, i * 0.07)),
  step: () => sweep(320, 240, 0.06, 'sine', 0.08),
  launch: () => { noise(0.9, 0.12, 900); sweep(120, 420, 0.9, 'sawtooth', 0.05); },
  chest: () => { sweep(180, 330, 0.25, 'triangle', 0.14); [784, 988, 1319].forEach((f, i) => tone(f, 0.22, 'triangle', 0.1, 0.25 + i * 0.09)); },
};
export const soft = (): void => tone(196, 0.25, 'sine', 0.1); // never a buzzer
export const praise = (): void => {
  const pool: [number, number, number][] = [
    [523.3, 659.3, 784.0], [587.3, 740, 880], [440, 554.4, 659.3], [659.3, 784, 988], [392, 523.3, 659.3],
  ];
  const [a, b, c] = pool[Math.floor(Math.random() * pool.length)] as [number, number, number];
  tone(a, 0.18, 'triangle', 0.16);
  tone(b, 0.18, 'triangle', 0.16, 0.12);
  tone(c, 0.3, 'triangle', 0.16, 0.24);
};

/** Play a sequence of sounds; `onStep(i)` fires as each starts. */
export const playSequence = async (phonemes: string[], onStep?: (i: number) => void, gapMs = 620): Promise<void> => {
  for (let i = 0; i < phonemes.length; i++) {
    onStep?.(i);
    blip(phonemes[i] as string);
    await new Promise((r) => setTimeout(r, gapMs));
  }
  onStep?.(-1);
};

const browserSpeech = (text: string): void => {
  if (muted || !('speechSynthesis' in window)) return;
  try {
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'en-GB';
    u.rate = 0.8;
    window.speechSynthesis.speak(u);
  } catch {
    /* no speech available: captions carry the meaning */
  }
};

/** Say a word, or a short list ("cat, hat"). Uses a generated clip when one exists, browser speech otherwise. */
export const speak = (text: string): void => {
  const parts = text.split(/,\s*/);
  const clips = parts.map((p) => manifest?.words[p.toLowerCase()]);
  if (clips.every(Boolean)) {
    void (async () => {
      for (const rel of clips as string[]) {
        const buf = await loadBuffer(rel);
        if (!buf) return browserSpeech(text);
        await play(buf, 1.0, true);
        await new Promise((r) => setTimeout(r, 120));
      }
    })();
  } else browserSpeech(text);
};

/** A fixed phrase from the manifest (e.g. "play", "two_minutes"). */
export const sayPhrase = (key: string, fallbackText: string): void => {
  const rel = manifest?.phrases[key];
  if (!rel) return browserSpeech(fallbackText);
  void loadBuffer(rel).then((buf) => (buf ? play(buf, 1.0, true) : browserSpeech(fallbackText)));
};
